"""Python 3.11+; stdlib. Streaming row validation with explicit quarantine."""
import csv
import io
import json
from decimal import Decimal, InvalidOperation
from pathlib import Path
from tempfile import TemporaryDirectory


def ingest(source, accepted, rejected):
    reader = csv.DictReader(source)
    if reader.fieldnames != ["id", "currency", "amount"]:
        raise ValueError("header must be id,currency,amount")
    counts = {"accepted": 0, "rejected": 0}
    for number, row in enumerate(reader, 2):
        error = None
        try:
            if None in row or any(v is None for v in row.values()):
                raise ValueError("wrong column count")
            identity = row["id"].strip()
            currency = row["currency"].strip().upper()
            raw = row["amount"].strip()
            if not identity or len(identity) > 64:
                raise ValueError("invalid id")
            if currency not in {"USD", "INR"}:
                raise ValueError("unsupported currency")
            amount = Decimal(raw)
            if not amount.is_finite() or amount < 0 or amount > Decimal("1000000"):
                raise ValueError("amount out of range")
            if amount != amount.quantize(Decimal("0.01")):
                raise ValueError("fractional cent")
            normalized = {"id": identity, "currency": currency, "amount": format(amount, ".2f")}
        except (ValueError, InvalidOperation) as exc:
            error = str(exc) or "invalid decimal"
        if error is not None:
            rejected.write(json.dumps({"row": number, "raw": row, "reason": error}) + "\n")
            counts["rejected"] += 1
        else:
            accepted.write(json.dumps(normalized) + "\n")
            counts["accepted"] += 1
    return counts


def main():
    fixture = "id,currency,amount\n a1 , usd ,10.00\na2,INR,NaN\na3,USD,0.001\na4,EUR,2\na5,USD,2,extra\na6,INR,0\n"
    with TemporaryDirectory() as directory:
        folder = Path(directory)
        with (folder / "ok.jsonl").open("w") as good, (folder / "bad.jsonl").open("w") as bad:
            counts = ingest(io.StringIO(fixture), good, bad)
        rows = [json.loads(x) for x in (folder / "ok.jsonl").read_text().splitlines()]
        errors = [json.loads(x) for x in (folder / "bad.jsonl").read_text().splitlines()]
        assert counts == {"accepted": 2, "rejected": 4}
        assert rows[0] == {"id": "a1", "currency": "USD", "amount": "10.00"}
        assert rows[1]["amount"] == "0.00"
        assert len(errors) == 4 and all(x["raw"] and x["reason"] for x in errors)
        try:
            ingest(io.StringIO("wrong,header\n"), io.StringIO(), io.StringIO())
        except ValueError:
            pass
        else:
            raise AssertionError("bad header accepted")
    print("PASS streaming CSV: 2 accepted, 4 quarantined, header rejected")


if __name__ == "__main__":
    main()

"""Python 3.11+; stdlib. Explicit line rounding and replay-safe invoice ledger."""
from decimal import Decimal, ROUND_HALF_UP


class Conflict(ValueError):
    pass


def line_total(price_text, quantity):
    if not isinstance(price_text, str) or len(price_text) > 32:
        raise ValueError("price must be a short decimal string")
    price = Decimal(price_text)
    if not price.is_finite() or price < 0 or price > Decimal("1000000"):
        raise ValueError("invalid price")
    if type(quantity) is not int or not 1 <= quantity <= 10000:
        raise ValueError("invalid quantity")
    return (price * quantity).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class Ledger:
    def __init__(self):
        self.entries = {}

    def post(self, invoice_id, currency, lines):
        if not invoice_id or currency not in {"USD", "INR"} or not lines:
            raise ValueError("invalid invoice")
        payload = (currency, tuple((price, qty) for price, qty in lines))
        total = sum((line_total(price, qty) for price, qty in lines), Decimal("0.00"))
        previous = self.entries.get(invoice_id)
        if previous is not None:
            if previous[0] != payload:
                raise Conflict("invoice id reused with a different payload")
            return previous[1]
        receipt = {"invoice": invoice_id, "currency": currency, "total": format(total, ".2f")}
        self.entries[invoice_id] = (payload, receipt)
        return receipt


def main():
    ledger = Ledger()
    first = ledger.post("inv-1", "USD", [("0.005", 1), ("0.005", 1)])
    assert first["total"] == "0.02"  # Round each line, then sum.
    assert ledger.post("inv-1", "USD", [("0.005", 1), ("0.005", 1)]) is first
    assert len(ledger.entries) == 1
    for operation in (
        lambda: ledger.post("inv-1", "INR", [("0.005", 1), ("0.005", 1)]),
        lambda: ledger.post("inv-1", "USD", [("1.00", 1)]),
    ):
        try:
            operation()
        except Conflict:
            pass
        else:
            raise AssertionError("changed replay accepted")
    for price, qty in [("NaN", 1), ("-1", 1), ("Infinity", 1), ("1", True), ("1", 0)]:
        try:
            line_total(price, qty)
        except ValueError:
            pass
        else:
            raise AssertionError("invalid amount/quantity accepted")
    assert ledger.post("inv-2", "INR", [("19.995", 3)])["total"] == "59.99"
    print("PASS Decimal ledger: rounding, unchanged replay, conflicts, invalid inputs")


if __name__ == "__main__":
    main()

"""Python 3.11+; stdlib. Simulated provider, no external charges or waits."""
class TransientError(Exception):
    pass


class PermanentError(Exception):
    pass


class UnknownOutcome(Exception):
    pass


class Provider:
    def __init__(self, mode):
        self.mode = mode
        self.receipts = {}
        self.attempts = 0
        self.effects = 0

    def submit(self, key, amount):
        self.attempts += 1
        if key in self.receipts:
            stored_amount, receipt = self.receipts[key]
            if stored_amount != amount:
                raise PermanentError("idempotency key payload mismatch")
            return receipt
        if self.mode == "permanent":
            raise PermanentError("request rejected")
        if self.mode == "always-transient":
            raise TransientError("unavailable before acceptance")
        self.effects += 1
        receipt = {"key": key, "amount": amount, "status": "accepted"}
        self.receipts[key] = (amount, receipt)
        if self.mode == "ambiguous" and self.attempts == 1:
            raise TransientError("connection failed after durable acceptance")
        return receipt


def submit_with_retry(provider, key, amount, max_attempts=3, sleep=lambda _: None):
    if type(max_attempts) is not int or max_attempts < 1 or max_attempts > 5:
        raise ValueError("attempt budget must be 1..5")
    for attempt in range(max_attempts):
        try:
            return provider.submit(key, amount)
        except TransientError as exc:
            if attempt + 1 == max_attempts:
                raise UnknownOutcome("budget exhausted; reconcile using original key") from exc
            sleep(min(0.1 * 2 ** attempt, 0.5))
    raise AssertionError("unreachable")


def main():
    waits = []
    provider = Provider("ambiguous")
    receipt = submit_with_retry(provider, "order-7", "20.00", sleep=waits.append)
    assert receipt["status"] == "accepted" and provider.effects == 1
    assert provider.attempts == 2 and waits == [0.1]
    try:
        submit_with_retry(provider, "order-7", "21.00")
    except PermanentError:
        pass
    else:
        raise AssertionError("different payload reused key")
    down = Provider("always-transient")
    waits = []
    try:
        submit_with_retry(down, "order-8", "20.00", sleep=waits.append)
    except UnknownOutcome:
        pass
    else:
        raise AssertionError("exhaustion silently accepted")
    assert down.attempts == 3 and down.effects == 0 and waits == [0.1, 0.2]
    rejected = Provider("permanent")
    try:
        submit_with_retry(rejected, "order-9", "20.00")
    except PermanentError:
        pass
    else:
        raise AssertionError("permanent rejection hidden")
    assert rejected.attempts == 1
    print("PASS bounded retries: ambiguous replay exactly one simulated effect; exhausted/permanent visible")


if __name__ == "__main__":
    main()

"""Python 3.11+; stdlib. Fixed workers, bounded queue, explicit outcomes."""
import asyncio


async def process(values, workers=3, capacity=4):
    if workers < 1 or capacity < 1:
        raise ValueError("positive worker count and capacity required")
    queue = asyncio.Queue(maxsize=capacity)
    outcomes = [None] * len(values)
    stats = {"active": 0, "max_active": 0, "max_queued": 0}
    sentinel = object()

    async def worker():
        while True:
            item = await queue.get()
            try:
                if item is sentinel:
                    return
                index, value = item
                stats["active"] += 1
                stats["max_active"] = max(stats["max_active"], stats["active"])
                try:
                    await asyncio.sleep(0)
                    if value < 0:
                        raise ValueError("negative fixture")
                    outcomes[index] = {"index": index, "status": "ok", "value": value * 2}
                except ValueError as exc:
                    outcomes[index] = {"index": index, "status": "error", "reason": str(exc)}
                finally:
                    stats["active"] -= 1
            finally:
                queue.task_done()

    async with asyncio.TaskGroup() as group:
        for _ in range(workers):
            group.create_task(worker())
        for index, value in enumerate(values):
            await queue.put((index, value))
            stats["max_queued"] = max(stats["max_queued"], queue.qsize())
        for _ in range(workers):
            await queue.put(sentinel)
        await queue.join()
    assert all(result is not None for result in outcomes)
    return outcomes, stats


async def main():
    values = list(range(100)) + [-1]
    outcomes, stats = await process(values)
    assert len(outcomes) == 101 and [x["index"] for x in outcomes] == list(range(101))
    assert outcomes[-1] == {"index": 100, "status": "error", "reason": "negative fixture"}
    assert outcomes[99]["value"] == 198
    assert stats["max_active"] <= 3 and stats["max_queued"] <= 4 and stats["active"] == 0
    empty, _ = await process([])
    assert empty == []
    try:
        await process(["programmer-bug"])
    except ExceptionGroup as exc:
        assert any(isinstance(error, TypeError) for error in exc.exceptions)
    else:
        raise AssertionError("unexpected programmer error swallowed")
    cancelled = asyncio.create_task(process(list(range(1000))))
    await asyncio.sleep(0)
    cancelled.cancel()
    try:
        await cancelled
    except asyncio.CancelledError:
        pass
    else:
        raise AssertionError("external cancellation swallowed")
    assert not [t for t in asyncio.all_tasks() if t is not asyncio.current_task() and not t.done()]
    print("PASS bounded queue: 101 ordered outcomes, explicit row failure, worker/queue bounds")


if __name__ == "__main__":
    asyncio.run(main())
